#define main legacy_main
#include "mdh-cuda/main.cu"
#undef main
#include "mdh-cuda/WKFUtils.cu"
#include <vector>
#include <chrono>
#include <cmath>
int main(){const int na=129,n=1024;std::vector<float>ax(na),ay(na),az(na),q(na),sz(na),gx(n),gy(n),gz(n),want(n),out(n);for(int i=0;i<na;i++){ax[i]=float(i%17)/64;ay[i]=float(i%13)/64;az[i]=float(i%11)/64;q[i]=float(i%17+1)/1024;sz[i]=float(i%4+1)/8;}for(int j=0;j<n;j++){gx[j]=1.f+float(j%31)/64;gy[j]=1.f+float((7*j)%37)/64;gz[j]=1.f+float((11*j)%41)/64;double sum=0;for(int i=0;i<na;i++){double dx=double(gx[j])-ax[i],dy=double(gy[j])-ay[i],dz=double(gz[j])-az[i],d=sqrt(dx*dx+dy*dy+dz*dz);sum+=double(q[i])/d*exp(-.125*(d-sz[i]))/(1+.125*sz[i]);}want[j]=sum;}float *da,*db,*dc,*dq,*ds,*dx,*dy,*dz,*dv;auto alloc=[](const std::vector<float>&h,float**d){cudaMalloc(d,h.size()*4);cudaMemcpy(*d,h.data(),h.size()*4,cudaMemcpyHostToDevice);};alloc(ax,&da);alloc(ay,&db);alloc(az,&dc);alloc(q,&dq);alloc(sz,&ds);alloc(gx,&dx);alloc(gy,&dy);alloc(gz,&dz);cudaMalloc(&dv,n*4);auto run=[&](int m){if(m==0)mdh<<<4,64,1280>>>(da,db,dc,dx,dy,dz,dq,ds,dv,1.f,.125f,na);else if(m==1)mdh2<<<4,64,1280>>>(da,db,dc,dx,dy,dz,dq,ds,dv,1.f,.125f,na);else mdh3<<<4,64,1280>>>(da,db,dc,dx,dy,dz,dq,ds,dv,1.f,.125f,na);};for(int m=0;m<3;m++){run(m);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;}for(int trial=1;trial<=5;trial++){double total=0,err=0;bool ok=true;std::vector<float>all;for(int m=0;m<3;m++){cudaDeviceSynchronize();auto t=std::chrono::steady_clock::now();for(int k=0;k<10;k++)run(m);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/10;cudaMemcpy(out.data(),dv,n*4,cudaMemcpyDeviceToHost);for(int i=0;i<n;i++){err=std::max(err,double(fabsf(out[i]-want[i])));ok=ok&&std::isfinite(out[i])&&out[i]>0&&fabsf(out[i]-want[i])<=1e-3f;}all.insert(all.end(),out.begin(),out.end());}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(all.data(),4,all.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.15g,\"timing_region\":\"sum_three_vector_kernel_bulk_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",all.size(),err,path,all.size());if(!ok)return 1;}cudaFree(da);cudaFree(db);cudaFree(dc);cudaFree(dq);cudaFree(ds);cudaFree(dx);cudaFree(dy);cudaFree(dz);cudaFree(dv);}
